CREATE VIEW analitica.v_fact_sales_enriched AS
 SELECT fs.transaction_id,
    fs.transaction_date,
    fs.transaction_time,
    fs.transaction_qty,
    fs.store_id,
    fs.product_id,
    fs.customer_id,
    fs.employee_id,
    fs.payment_methods_id,
    fs.total_amount,
    p.unit_price
   FROM (analitica.fact_sales fs
     JOIN analitica.dim_product p ON ((fs.product_id = p.product_id)))
  ORDER BY fs.transaction_id;


