--
-- TOC entry 234 (class 1259 OID 99086)
-- Name: v_kpi_sales_by_product; Type: VIEW; Schema: analitica; Owner: postgres
--

CREATE VIEW analitica.v_kpi_sales_by_product AS
 SELECT fs.product_id,
    p.product_category,
    p.product_type,
    count(DISTINCT fs.transaction_id) AS orders,
    sum(fs.transaction_qty) AS units,
    sum(fs.total_amount) AS net_sales,
    (sum(fs.total_amount) / (NULLIF(count(DISTINCT fs.transaction_id), 0))::numeric) AS aov
   FROM (analitica.v_fact_sales_enriched fs
     JOIN analitica.dim_product p ON ((p.product_id = fs.product_id)))
  GROUP BY fs.product_id, p.product_category, p.product_type;


ALTER VIEW analitica.v_kpi_sales_by_product OWNER TO postgres;

--
-- TOC entry 235 (class 1259 OID 99091)
-- Name: v_kpi_sales_by_store; Type: VIEW; Schema: analitica; Owner: postgres
--

CREATE VIEW analitica.v_kpi_sales_by_store AS
 SELECT ds.store_location,
    count(DISTINCT fs.transaction_id) AS orders,
    sum(fs.transaction_qty) AS units,
    sum(fs.total_amount) AS net_sales,
    round((sum(fs.total_amount) / (NULLIF(count(DISTINCT fs.transaction_id), 0))::numeric), 2) AS aov,
    round((sum(fs.total_amount) / (NULLIF(sum(fs.transaction_qty), 0))::numeric), 2) AS net_avg_price
   FROM (analitica.fact_sales fs
     JOIN analitica.dim_store ds ON ((fs.store_id = ds.store_id)))
  GROUP BY ds.store_location
  ORDER BY (sum(fs.total_amount)) DESC;


ALTER VIEW analitica.v_kpi_sales_by_store OWNER TO postgres;

