CREATE VIEW analitica.v_kpi_sales_monthly AS
 SELECT EXTRACT(year FROM transaction_date) AS year,
    EXTRACT(month FROM transaction_date) AS month,
    to_char((transaction_date)::timestamp with time zone, 'FMMonth'::text) AS month_name,
    date_trunc('month'::text, (transaction_date)::timestamp with time zone) AS month_start,
    count(DISTINCT transaction_id) AS orders,
    sum(transaction_qty) AS units,
    sum(total_amount) AS net_sales,
    (sum(total_amount) / (NULLIF(count(DISTINCT transaction_id), 0))::numeric) AS aov,
    (sum(total_amount) / (NULLIF(sum(transaction_qty), 0))::numeric) AS net_avg_price
   FROM analitica.v_fact_sales_enriched
  GROUP BY (EXTRACT(year FROM transaction_date)), (EXTRACT(month FROM transaction_date)), (to_char((transaction_date)::timestamp with time zone, 'FMMonth'::text)), (date_trunc('month'::text, (transaction_date)::timestamp with time zone));


